// Phase 3 — T3.1: 毒性食物与植物数据库
// 数据来源: ASPCA Animal Poison Control, Pet Poison Helpline, AVMA, AAFP, AKC
// 基准: ≥200 条条目，涵盖 food / plant / household 三类

export type ToxicityLevel = 'toxic' | 'caution' | 'safe';
export type ToxicSpeciesScope = 'dog' | 'cat' | 'both';

export type ToxicItem = {
  slug: string;
  name: string;
  aliases: string[];
  category: 'food' | 'plant' | 'household';
  species: ToxicSpeciesScope;
  dogLevel: ToxicityLevel;
  catLevel: ToxicityLevel;
  symptoms: string[];
  safeAmount: string | null;
  source: string;
  emergencyNote: string | null;
  /** Why this item is dangerous — ≥100 chars of unique per-item text (geo-checklist §14.3). Falls back to auto-generated text if omitted. */
  dangerReason?: string;
  /** What to do if ingested — ≥60 chars of unique per-item emergency steps. Falls back to auto-generated text if omitted. */
  whatToDo?: string;
};

const F = 'food' as const;
const P = 'plant' as const;
